const pageScriptElement=document.currentScript,oid=pageScriptElement?.getAttribute("data-oid")||null,oid_likes=pageScriptElement?.getAttribute("data-oid-likes")||null;let liked_page=!1;const id=oid&&oid.replaceAll("/","-"),id_likes=oid_likes&&oid_likes.replaceAll("/","-");if(typeof auth!="undefined"){const e=localStorage.getItem(id);e||auth.signInAnonymously().then(()=>{const e=db.collection("views").doc(id);localStorage.setItem(id,!0),e.get().then(e=>{e.exists?db.collection("views").doc(id).update({views:firebase.firestore.FieldValue.increment(1)}):db.collection("views").doc(id).set({views:1})}).catch(e=>console.error("Error getting document:",e))}).catch(e=>console.error(e.code,e.message));const t=localStorage.getItem(id_likes);t&&(liked_page=!0,updateLikeButton(!0))}function updateLikeButton(e){const n=document.getElementById("button_likes_heart"),s=document.getElementById("button_likes_empty_heart"),o=document.getElementById("button_likes_text"),t=document.getElementById("button_likes");if(!n||!s||!o||!t)return;e?(n.style.display="inline-block",s.style.display="none",o.innerText=" Liked",t.classList.add("liked"),t.setAttribute("title","Click to unlike")):(n.style.display="none",s.style.display="inline-block",o.innerText=" Like",t.classList.remove("liked"),t.setAttribute("title","Click to like"))}function like_article(e){auth.signInAnonymously().then(()=>{const t=db.collection("likes").doc(e);t.get().then(t=>{liked_page=!0,localStorage.setItem(e,!0),updateLikeButton(!0),t.exists?db.collection("likes").doc(e).update({likes:firebase.firestore.FieldValue.increment(1)}):db.collection("likes").doc(e).set({likes:1})}).catch(e=>console.error("Error:",e))}).catch(e=>console.error(e.code,e.message))}function remove_like_article(e){auth.signInAnonymously().then(()=>{const t=db.collection("likes").doc(e);t.get().then(t=>{liked_page=!1,localStorage.removeItem(e),updateLikeButton(!1),t.exists&&db.collection("likes").doc(e).update({likes:firebase.firestore.FieldValue.increment(-1)})}).catch(e=>console.error("Error:",e))}).catch(e=>console.error(e.code,e.message))}function process_article(){liked_page?remove_like_article(id_likes):like_article(id_likes)}const likeButton=document.getElementById("button_likes");likeButton&&likeButton.addEventListener("click",()=>process_article())